    /**
     * Method to retrieve the Goal via an GoalPrimaryKey.
     * @param 	id Long
     * @return 	Goal
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Goal handle( FindGoalQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getGoalId() );
    }
    
    /**
     * Method to retrieve a collection of all Goals
     *
     * @param	query	FindAllGoalQuery 
     * @return 	List<Goal> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Goal> handle( FindAllGoalQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindGoal,
 * but only if the id matches
 *
 * @param		entity	Goal
 */
	protected void emitFindGoal( Goal entity ) {
		LOGGER.info("handling emitFindGoal" );
		
	    queryUpdateEmitter.emit(FindGoalQuery.class,
	                            query -> query.getFilter().getGoalId().equals(entity.getGoalId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllGoal
	 * 
	 * @param		entity	Goal
	 */
	protected void emitFindAllGoal( Goal entity ) {
		LOGGER.info("handling emitFindAllGoal" );
		
	    queryUpdateEmitter.emit(FindAllGoalQuery.class,
	                            query -> true,
	                            entity);
	}

